using System.Runtime.CompilerServices;
using System.Text.Json;
using MongoDB.Bson;
using Shoreline.Api.Features;
using Shoreline.Api.Infrastructure;
using Xunit;

namespace Shoreline.Tests;

/// <summary>
/// Golden vectors are generated by executing the authoritative Python source via AST.
/// They must never be edited to match C# behaviour.
/// </summary>
public sealed class FileGoldenTests
{
    [Fact]
    public void Filename_MatchesPythonGoldenVectors()
    {
        using var document = JsonDocument.Parse(File.ReadAllText(FixturePath()));
        foreach (var item in document.RootElement.GetProperty("filename").EnumerateArray())
        {
            var name = item.GetProperty("name").GetString()!;
            var folder = item.GetProperty("folder").GetBoolean();
            if (item.GetProperty("ok").GetBoolean())
            {
                var parsed = FileService.ParseFilename(name, folder);
                Assert.Equal(item.GetProperty("prefix").GetString(), parsed.Prefix);
                Assert.Equal(item.GetProperty("suffix").GetString(), parsed.Suffix);
                Assert.Equal(item.GetProperty("type").GetInt32(), parsed.Type);
                Assert.Equal(item.GetProperty("sort_name").GetString(), parsed.SortName);
            }
            else
            {
                var error = Assert.Throws<ApiError>(() => FileService.ParseFilename(name, folder));
                Assert.Equal(107, error.Code);
                Assert.Equal("文件名错误: " + item.GetProperty("error").GetString(), error.Message);
            }
        }
    }

    [Fact]
    public void OrderSnapshot_MatchesPythonGoldenVectors()
    {
        using var document = JsonDocument.Parse(File.ReadAllText(FixturePath()));
        foreach (var item in document.RootElement.GetProperty("order").EnumerateArray())
        {
            var rows = new List<BsonDocument>();
            foreach (var row in item.GetProperty("rows").EnumerateArray())
            {
                var documentRow = new BsonDocument
                {
                    ["_id"] = ObjectId.Parse(row[0].GetString()!),
                    ["n"] = row[1].GetString()!,
                };
                documentRow["mo"] = row[2].ValueKind == JsonValueKind.Null
                    ? BsonNull.Value
                    : new BsonInt32(row[2].GetInt32());
                rows.Add(documentRow);
            }

            Assert.Equal(item.GetProperty("json").GetString(), FileService.SnapshotJson(rows));
            Assert.Equal(item.GetProperty("sha256").GetString(), FileService.SnapshotVersion(rows));
        }
    }

    private static string FixturePath([CallerFilePath] string sourceFile = "")
        => Path.Combine(Path.GetDirectoryName(sourceFile)!, "Fixtures", "file-goldens.json");
}
